#include <algorithm>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

class Recent
{
public:
    void add(const std::string& path) {}
    const std::vector<std::string>& items() const { return m_items; }

private:
    std::vector<std::string> m_items{};
};

int main()
{
    Recent r{};
    for (const char* p : {"a", "b", "c", "a"}) r.add(p);
    for (const auto& i : r.items()) std::cout << i << ' ';
}
